(function(){'use strict';
const A=CraftApp,M=ProcurementAutoMath,$=id=>document.getElementById(id),fmt=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const launch=document.createElement('button');launch.type='button';launch.id='procurement-auto-open';launch.className='button';launch.textContent='Подобрать города';$('export').before(launch);
const dialog=document.createElement('dialog');dialog.id='procurement-auto-dialog';dialog.className='procurement-auto-dialog';dialog.setAttribute('aria-labelledby','procurement-auto-title');document.body.append(dialog);let session=null;
const message=document.createElement('p');message.id='procurement-auto-message';message.className='hint';message.setAttribute('role','status');message.hidden=true;document.querySelector('.materials-panel .section-heading').after(message);
function scope(){const x=A.snapshot(),draft=A.captureDraft();return JSON.stringify([Workspace.ticket(),x.recipe.id,x.config.quality,x.result.bill.map(m=>[m.id,m.buy]),x.config.purchaseSplits||{},draft.overrides,x.config.purchaseAuto||{}]);}
function materialRows(x){const overrides=A.captureDraft().overrides;return x.result.bill.map(m=>{const row={...m,key:CityAllocationMath.key(m.id,m,x.config.quality)};row.protected=M.protectedRow(row,x.config,overrides);return row;});}
function settings(){return {mode:$('procurement-auto-mode').value,cities:[...dialog.querySelectorAll('[data-auto-city]:checked')].map(n=>n.value),keepManual:$('procurement-auto-keep').checked};}
function compute(){const x=A.snapshot();return M.build(materialRows(x),settings(),(id,city)=>A.allocationBuyQuote(id,city));}
function signature(plan){return JSON.stringify([plan.settings,plan.rows.map(r=>[r.key,r.quantity,r.locked,r.currentCost,r.candidates.map(c=>[c.city,c.price,c.manual,c.source])])]);}
function close(restore=true){const prior=session;session=null;if(dialog.open)dialog.close();if(restore&&prior?.focus?.isConnected&&prior.focus.checkVisibility())prior.focus.focus({preventScroll:true});}
function total(value){return value===null?'Есть неизвестные цены':fmt(value)+' серебра';}
function paint(){if(!session)return;const status=$('procurement-auto-status'),host=$('procurement-auto-plan'),apply=$('procurement-auto-apply');
 if(session.scope!==scope()){close(false);return;}
 try{const plan=compute();session.plan=plan;session.signature=signature(plan);const busy=$('refresh').disabled;apply.disabled=busy||!plan.canApply;$('procurement-auto-refresh').disabled=busy;
  const saving=plan.saving===null?'Сравнение с текущей закупкой недоступно: есть неизвестные цены.':Math.abs(plan.saving)<.005?'Стоимость совпадает с текущей закупкой.':plan.saving>0?'Дешевле текущей закупки на '+fmt(plan.saving)+' серебра.':'Дороже текущей закупки на '+fmt(-plan.saving)+' серебра.';
  status.textContent=busy?'Загружаем цены…':plan.rows.length===0?'В партии нет материалов к закупке. Проверьте её объём.':plan.autoCount===0?'Все материалы сохранены вручную. Отключите сохранение ручных настроек, чтобы подобрать их заново.':!plan.canApply?'Не для всех материалов найдена проверенная цена в выбранных городах. Измените города или обновите цены.':saving;
  host.innerHTML='<div class="procurement-auto-totals"><div><small>Сейчас, материалы</small><strong>'+total(plan.currentTotal)+'</strong></div><div><small>Предлагаемая закупка</small><strong>'+total(plan.total)+'</strong></div></div><div class="procurement-auto-compare"><p>Минимум по материалам: <b>'+total(plan.split.total)+'</b></p><p>Один город'+(plan.single.city?' · '+esc(plan.single.city):'')+': <b>'+total(plan.single.total)+'</b></p></div><p class="hint">Подобрано ресурсов: '+plan.autoCount+' · Сохранено вручную: '+plan.protectedCount+'. Сравнение включает сохранённые строки; они могут оставаться в других городах.</p>'+plan.rows.filter(r=>!r.ready).map(r=>'<p class="negative">'+esc(ALBION_DATA.names[r.id]||r.id)+': '+(r.locked?'сохранённая закупка требует количества или цены.':'нет подходящей цены для '+fmt(r.quantity)+' шт.')+'</p>').join('')+plan.groups.map(group=>'<section class="procurement-auto-group"><div><h3>'+esc(group.city)+'</h3><b>'+total(group.known?group.cost:null)+'</b></div>'+group.rows.map(row=>'<p><span>'+esc(ALBION_DATA.names[row.id]||row.id)+'<small>'+fmt(row.quantity)+' шт. × '+fmt(row.price)+' · '+esc(row.locked?'Сохранено вручную':row.source)+'</small></span><b>'+fmt(row.cost)+'</b></p>').join('')+'</section>').join('');
  apply.textContent='Применить к '+plan.changes.length+' ресурсам';
 }catch(error){session.plan=null;session.signature=null;host.replaceChildren();status.textContent=error.message;apply.disabled=true;}
}
function open(){if(dialog.open){dialog.querySelector('select').focus();return;}if(document.querySelector('dialog[open]'))return;const x=A.snapshot();let saved;try{saved=M.options(x.config.purchaseAuto);}catch{saved=M.options();}
 session={scope:scope(),focus:document.activeElement,plan:null,signature:null};
 dialog.innerHTML='<div class="procurement-auto-heading"><h2 id="procurement-auto-title">Подобрать города закупки</h2><button id="procurement-auto-close" class="button" type="button" aria-label="Закрыть">×</button></div><p id="procurement-auto-item"></p><label class="field">Способ закупки<select id="procurement-auto-mode"><option value="split">Самая низкая цена каждого материала</option><option value="single">Один город для подобранных материалов</option></select></label><fieldset id="procurement-auto-cities"><legend>Где можно покупать</legend>'+M.cities.map(city=>'<label><input type="checkbox" data-auto-city value="'+city+'"> '+city+'</label>').join('')+'</fieldset><label class="procurement-auto-keep"><input id="procurement-auto-keep" type="checkbox"> Сохранить мои цены, города и ручное распределение</label><p class="hint">Сравнивается стоимость материалов. Доставка задаётся отдельно. Количество уже включает возврат и запас. Источник не показывает доступное количество в ордерах: каждый материал предлагается купить целиком в выбранном городе.</p><p id="procurement-auto-status" role="status"></p><div id="procurement-auto-plan"></div><div class="procurement-auto-actions"><button id="procurement-auto-apply" class="button primary" type="button">Применить</button><button id="procurement-auto-cancel" class="button" type="button">Отмена</button><button id="procurement-auto-refresh" class="button" type="button">Обновить цены</button></div>';
 $('procurement-auto-item').textContent=x.recipe.name+' · '+fmt(x.result.amount)+' шт.';$('procurement-auto-mode').value=saved.mode;$('procurement-auto-keep').checked=saved.keepManual;for(const node of dialog.querySelectorAll('[data-auto-city]'))node.checked=saved.cities.includes(node.value);
 for(const id of ['procurement-auto-mode','procurement-auto-cities','procurement-auto-keep'])$(id).onchange=paint;
 $('procurement-auto-close').onclick=()=>close();$('procurement-auto-cancel').onclick=()=>close();$('procurement-auto-refresh').onclick=()=>{$('refresh').click();paint();};
 $('procurement-auto-apply').onclick=()=>{if(!session||session.scope!==scope()){close(false);return;}if($('refresh').disabled)return;try{const fresh=compute();if(signature(fresh)!==session.signature){paint();$('procurement-auto-status').textContent='Цены изменились. План пересчитан — проверьте новые суммы и примените ещё раз.';return;}const patch=M.patch(fresh,A.snapshot().config);session.applying=true;A.setCityAllocation(patch);Workspace.capture();message.textContent='Города подобраны для '+fresh.changes.length+' ресурсов. При изменении объёма партии пересчитайте закупку.';message.hidden=false;close();}catch(error){$('procurement-auto-status').textContent=error.message;}};
 dialog.showModal();paint();$('procurement-auto-mode').focus();
}
launch.onclick=open;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('workspacechange',event=>{if(event.detail?.navigation!==false)message.hidden=true;if(session&&!session.applying&&session.scope!==scope())close(false);});document.addEventListener('craftresultchange',()=>{if(session&&!session.applying){if(session.scope!==scope())close(false);else paint();}});
window.ProcurementAutoUI={open,close,snapshot:()=>session?{scope:session.scope,plan:session.plan,signature:session.signature}:null};
})();
